  KEY `FK_INVOICE_ITEMS_UNIT_ID` (`UNIT_ID`),
  CONSTRAINT `FK_INVOICE_ITEMS_ASSET_ACCOUNT_ID` FOREIGN KEY (`ASSET_ACCOUNT_ID`) REFERENCES `account` (`ID`),
