/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `object_code_sequence` (
  `ID` int unsigned NOT NULL AUTO_INCREMENT,
  `OBJECT_TYPE` tinyint unsigned NOT NULL,
  `LOCATION_ID` int unsigned DEFAULT NULL,
