 := S + \'Phone \' + Report.Parameters[\'CompanyPhoneNo\'];\r\n  end;\r\n  if Report.Parameters[\'CompanyMobileNo\'] <> \'\' then\r\n  begin\r\n    if S <> \'\' then S := S + Sep;\r\n    S := S + \'Mobile \' +  Report.Parameters[\'CompanyMobileNo\'];\r\n  end;\r\n  if Report.Parameters[\'CompanyFaxNo\'] <> \'\' then\r\n  begin\r\n    if S <> \'\' then S := S + Sep;\r\n    S := S + \'Fax \' +  Report.Parameters[\'CompanyFaxNo\'];\r\n  end;\r\n  if Report.Parameters[\'CompanyTin\'] <> \'\' then\r\n  begin\r\n    if S <> \'\' then S := S + Sep;\r\n    S := S + \'Tin \' +  Report.Parameters[\'CompanyTin\'];\r\n  end;\r\n  CompanyContactInfo.Text := S;\r\n  \r\n  if not ByPass then\r\n  begin\r\n    ChrWidth := CompanyContactInfo.Width / Length(CompanyContactInfo.Text);\r\n    CoContactInfoWidth := ChrWidth * (Length(S) - 1);\r\n    CoContactInfoLeft := CompanyContactInfo.Left + \r\n      (CompanyContactInfo.Width - CoContactInfoWidth);\r\n  end;\r\n  if CoContactInfoLeft < HeaderBar.Left then\r\n  begin\r\n    HeaderBar.Left := CoContactInfoLeft;\r\n    HeaderBar.Width := BandWidth - HeaderBar.Left;\r\n  end;\r\n  \r\n  ByPass := True;\r\nend;\r\n\0\0TraProgramInforaProgramInfo2raClassNameTraEventHandlerraProgram.ProgramNameHeaderBeforePrintraProgram.ProgramTypettProcedureraProgram.SourceAprocedure HeaderBeforePrint;\r\nbegin\r\n  FormatReportTitle;\r\nend;\r\nraProgram.ComponentNameHeaderraProgram.EventNameBeforePrintraProgram.EventID\0\0TraProgramInforaProgramInfo3raClassNameTraEventHandlerraProgram.ProgramNameUnitCostOnCalcraProgram.ProgramTypettProcedureraProgram.Sourceprocedure UnitCostOnCalc(var Value: Variant);\r\nbegin\r\n  Value := plBuildAssembly[\'AMOUNT\'] / plBuildAssembly[\'QUANTITY\'];\r\nend;\r\nraProgram.ComponentNameUnitCostraProgram.EventNameOnCalcraProgram.EventID!\0\0TraProgramInforaProgramInfo4raClassNameTraEventHandlerraProgram.ProgramNameBuildUnitCostOnCalcraProgram.ProgramTypettProcedureraP