rmatDateRange;\r\nvar\r\n  YearFrom: Integer;\r\n  MonthFrom: Integer;\r\n  DayFrom: Integer;\r\n  YearTo: Integer;\r\n  MonthTo: Integer;\r\n  DayTo: Integer;\r\n  RangeFrom: TDateTime;\r\n  RangeTo: TDateTime;\r\n  S: string;\r\nbegin\r\n  if Report.Parameters.InList(\'RangeTo\') then\r\n  begin\r\n    RangeFrom := Report.Parameters[\'RangeFrom\'];\r\n    RangeTo := Report.Parameters[\'RangeTo\'];\r\n    DecodeDate(RangeFrom, YearFrom, MonthFrom, DayFrom);\r\n    DecodeDate(RangeTo, YearTo, MonthTo, DayTo);\r\n    if YearFrom = YearTo then\r\n    begin\r\n      if MonthFrom = MonthTo then\r\n      begin\r\n        if DayFrom = DayTo then\r\n          S := FormatDateTime(\'mmmm d, yyyy\', RangeTo)\r\n        else\r\n          S := FormatDateTime(\'mmmm \' + IntToStr(DayFrom) +\r\n            \' - \' + IntToStr(DayTo)  + \', yyyy\', RangeTo);\r\n      end\r\n      else\r\n      begin\r\n        S := FormatDateTime(\'mmmm d\', RangeFrom);\r\n        S := S + \' through \' + FormatDateTime(\'mmmm d, yyyy\', RangeTo);\r\n      end;\r\n    end\r\n    else\r\n    begin\r\n      S := FormatDateTime(\'mmmm d, yyyy\', RangeFrom);\r\n      S := S + \' through \' + FormatDateTime(\'mmmm d, yyyy\', RangeTo);\r\n    end;\r\n    DateRangeLabel.Text := S;\r\n  end\r\n  else\r\n    DateRangeLabel.Text := \'All transactions\';\r\nend;\r\n\0TraEventHandlerProgramNameTitleBeforePrintProgramTypettProcedureSourceTprocedure TitleBeforePrint;\r\nbegin\r\n  FormatReportTitle;\r\n  FormatDateRange;\r\nend;\r\n\rComponentNameTitle	EventNameBeforePrintEventID\0TraEventHandlerProgramNameGrandTotalOnCalcProgramTypettProcedureSourceqprocedure GrandTotalOnCalc(var Value: Variant);\r\nbegin\r\n  Value := Value + plBuildAssemblyList[\'AMOUNT\'];\r\nend;\r\n\rComponentName\nGrandTotal	EventNameOnCalcEventID!\0TraEventHandlerProgramNameSubTitleOnCalcProgramTypettProcedureSource½procedure SubTitleOnCalc(var Value: Variant);\r\nbegin\r\n  if Report.Paramete