 CoNameWidth);\r\n  end;\r\n  HeaderBar.Left := CoNameLeft;\r\n  HeaderBar.Width := BandWidth - HeaderBar.Left;\r\n  CompanyName.Text := S;\r\n  \r\n  CompanyAddress.Lines.Clear;\r\n  CompanyAddress.Lines.Add(Report.Parameters[\'CompanyAddress\']);\r\n  S := \'\';\r\n  Sep := \' â€¢ \';\r\n  if Report.Parameters[\'CompanyEmailAddress\'] <> \'\' then\r\n    S := Report.Parameters[\'CompanyEmailAddress\'];\r\n  if Report.Parameters[\'CompanyPhoneNo\'] <> \'\' then\r\n  begin\r\n    if S <> \'\' then S := S + Sep;\r\n    S := S + \'Phone \' + Report.Parameters[\'CompanyPhoneNo\'];\r\n  end;\r\n  if Report.Parameters[\'CompanyMobileNo\'] <> \'\' then\r\n  begin\r\n    if S <> \'\' then S := S + Sep;\r\n    S := S + \'Mobile \' +  Report.Parameters[\'CompanyMobileNo\'];\r\n  end;\r\n  if Report.Parameters[\'CompanyFaxNo\'] <> \'\' then\r\n  begin\r\n    if S <> \'\' then S := S + Sep;\r\n    S := S + \'Fax \' +  Report.Parameters[\'CompanyFaxNo\'];\r\n  end;\r\n  if Report.Parameters[\'CompanyTin\'] <> \'\' then\r\n  begin\r\n    if S <> \'\' then S := S + Sep;\r\n    S := S + \'Tin \' +  Report.Parameters[\'CompanyTin\'];\r\n  end;\r\n  CompanyContactInfo.Text := S;\r\n  \r\n  if not ByPass then\r\n  begin\r\n    ChrWidth := CompanyContactInfo.Width / Length(CompanyContactInfo.Text);\r\n    CoContactInfoWidth := ChrWidth * (Length(S) - 1);\r\n    CoContactInfoLeft := CompanyContactInfo.Left + \r\n      (CompanyContactInfo.Width - CoContactInfoWidth);\r\n  end;\r\n  if CoContactInfoLeft < HeaderBar.Left then\r\n  begin\r\n    HeaderBar.Left := CoContactInfoLeft;\r\n    HeaderBar.Width := BandWidth - HeaderBar.Left;\r\n  end;\r\n  \r\n  ByPass := True;\r\nend;\r\n\0\nTraProgram	ChildTypeProgramNameFormatDateRangeProgramTypettProcedureSource\Ø\0\0procedure FormatDateRange;\r\nvar\r\n  YearFrom: Integer;\r\n  MonthFrom: Integer;\r\n  DayFrom: Integer;\r\n  YearTo: Integer;\r\n  MonthTo: Integer;\r\n  DayTo: Integer;\r\n  RangeFrom: TDateTime;\r\n  RangeTo: TDateTime;\r\n  S: string;\r\nbegin\r\n  if Report.Parameters.InList(\'RangeTo\') then\r\n  begin\r\n    RangeFrom := Report.Parameters[\'RangeFrom\'];\r\n    RangeTo := Report.Parameters[\'RangeTo\'];\r\n    DecodeDate(RangeFrom, YearFrom, MonthFrom, DayFrom);\r\n    DecodeDate(RangeTo, YearTo, MonthTo, DayTo);\r\n    if YearFrom = YearTo then\r\n    begin\r\n      if MonthFrom = MonthTo then\r\n      begin\r\n        if DayFrom = DayTo then\r\n          S := FormatDateTime(\'mmmm d, yyyy\', RangeTo)\r\n        else\r\n          S := FormatDateTime(\'mmmm \' + IntToStr(DayFrom) +\r\n            \' - \' + IntToStr(DayTo)  + \', yyyy\', RangeTo);\r\n      end\r\n      else\r\n      begin\r\n        S := FormatDateTime(\'mmmm d\', RangeFrom);\r\n        S := S + \' through \' + FormatDateTime(\'mmmm d, yyyy\', RangeTo);\r\n      end;\r\n    end\r\n    else\r\n    begin\r\n      S := FormatDateTime(\'mmmm d, yyyy\', RangeFrom);\r\n      S := S + \' through \' + FormatDateTime(\'mmmm d, yyyy\', RangeTo);\r\n    end;\r\n    DateRangeLabel.Text := S;\r\n  end\r\n  else\r\n    DateRangeLabel.Text := \'All transactions\';\r\nend;\r\n\0TraEventHandlerProgramNameTitleBeforePrintProgramTypettProcedureSourceTprocedure TitleBeforePrint;\r\nbegin\r\n  FormatReportTitle;\r\n  FormatDateRange;\r\nend;\r\n\rComponentNameTitle	EventNameBeforePrintEventID\0TraEventHandlerProgramNameSubTitleOnCalcProgramTypettProcedureSource½procedure SubTitleOnCalc(var Value: Variant);\r\nbegin\r\n  if Report.Parameters.InList(\'SubTitle\') then\r\n    Value := Report.Parameters[\'SubTitle\']\r\n  else\r\n    Value := \'All Records\';\r\nend;\r\n\rComponentNameSubTitle	EventNameOnCalcEventID!\0\0\0\0TppParameterListppParameterList2\0TppParameterCompanyNameDataTypedtStringValueActive Systems\0\0TppParameterCompanyAddressDataTypedtStringValue-#41 1st Street PH2-B, Monte Maria, Davao City\0\0TppParameterCompanyPhoneNoDataTypedtStringValue\0\0\0TppPa