    end\r\n    else\r\n    begin\r\n      S := FormatDateTime(\'mmmm d, yyyy\', RangeFrom);\r\n      S := S + \' through \' + FormatDateTime(\'mmmm d, yyyy\', RangeTo);\r\n    end;\r\n    DateRangeLabel.Text := S;\r\n  end\r\n  else\r\n    DateRangeLabel.Text := \'All transactions\';\r\nend;\r\n\0\0TraProgramInforaProgramInfo3raClassName\nTraProgramraProgram.ChildTyperaProgram.IsFunctionType	raProgram.ProgramNameTryTextToNumberraProgram.ProgramType\nttFunctionraProgram.Source±\0\0function TryTextToNumber(const Text: string): Integer;\r\nvar\r\n  I: Integer;\r\n  C: Char;\r\n  Combined: string;\r\nbegin\r\n  Combined := \'\';\r\n  for I := 1 to Length(Text) do\r\n  begin\r\n    C := Copy(Text, I, 1);\r\n    if (C >= \'0\') and (C<=\'9\') then\r\n      Combined := Combined + C;\r\n  end;\r\n  Combined := Copy(Combined, (Length(Combined)-9)+1, 9);\r\n  if Combined <> \'\' then\r\n    Result := StrToInt(Combined)\r\n  else\r\n    Result := 0;\r\nend;\r\nraProgram.CaretPos\0\0\0TraProgramInforaProgramInfo4raClassNameTraEventHandlerraProgram.ProgramNameTitleBeforePrintraProgram.ProgramTypettProcedureraProgram.SourceTprocedure TitleBeforePrint;\r\nbegin\r\n  FormatReportTitle;\r\n  FormatDateRange;\r\nend;\r\nraProgram.ComponentNameTitleraProgram.EventNameBeforePrintraProgram.EventIDraProgram.CaretPos\0\0\0TraProgramInforaProgramInfo5raClassNameTraEventHandlerraProgram.ProgramNameGrandTotalOnCalcraProgram.ProgramTypettProcedureraProgram.Sourcekprocedure GrandTotalOnCalc(var Value: Variant);\r\nbegin\r\n  Value := Value + plPaymentList[\'AMOUNT\'];\r\nend;\r\nraProgram.ComponentName\nGrandTotalraProgram.EventNameOnCalcraProgram.EventID!raProgram.CaretPos\0\0\0TraProgramInforaProgramInfo6raClassNameTraEventHandlerraProgram.ProgramNameSubTitleOnCalcraProgram.ProgramTypettProcedureraProgram.Source½procedure SubTitleOnCalc(var Value: Variant);\r\nbegin\r\n  if Report.Parameters.InList(\'Sub