 if S <> \'\' then S := S + Sep;\r\n    S := S + \'Phone \' + Report.Parameters[\'CompanyPhoneNo\'];\r\n  end;\r\n  if Report.Parameters[\'CompanyMobileNo\'] <> \'\' then\r\n  begin\r\n    if S <> \'\' then S := S + Sep;\r\n    S := S + \'Mobile \' +  Report.Parameters[\'CompanyMobileNo\'];\r\n  end;\r\n  if Report.Parameters[\'CompanyFaxNo\'] <> \'\' then\r\n  begin\r\n    if S <> \'\' then S := S + Sep;\r\n    S := S + \'Fax \' +  Report.Parameters[\'CompanyFaxNo\'];\r\n  end;\r\n  if Report.Parameters[\'CompanyTin\'] <> \'\' then\r\n  begin\r\n    if S <> \'\' then S := S + Sep;\r\n    S := S + \'Tin \' +  Report.Parameters[\'CompanyTin\'];\r\n  end;\r\n  CompanyContactInfo.Text := S;\r\n  \r\n  if not ByPass then\r\n  begin\r\n    ChrWidth := CompanyContactInfo.Width / Length(CompanyContactInfo.Text);\r\n    CoContactInfoWidth := ChrWidth * (Length(S) - 1);\r\n    CoContactInfoLeft := CompanyContactInfo.Left + \r\n      (CompanyContactInfo.Width - CoContactInfoWidth);\r\n  end;\r\n  if CoContactInfoLeft < HeaderBar.Left then\r\n  begin\r\n    HeaderBar.Left := CoContactInfoLeft;\r\n    HeaderBar.Width := BandWidth - HeaderBar.Left;\r\n  end;\r\n  \r\n  ByPass := True;\r\nend;\r\n\0\0TraProgramInforaProgramInfo2raClassName\nTraProgramraProgram.ChildTyperaProgram.ProgramNameFormatDateRangeraProgram.ProgramTypettProcedureraProgram.Sourceôprocedure FormatDateRange;\r\nbegin\r\n  if Report.Parameters.InList(\'RangeTo\') then\r\n    DateRangeLabel.Text := \'As of \' + FormatDateTime(\'mmmm d, yyyy\', Report.Parameters[\'RangeTo\'])\r\n  else\r\n    DateRangeLabel.Text := \'All transactions\';\r\nend;\r\n\0\0TraProgramInforaProgramInfo3raClassNameTraEventHandlerraProgram.ProgramNameTitleBeforePrintraProgram.ProgramTypettProcedureraProgram.SourceTprocedure TitleBeforePrint;\r\nbegin\r\n  FormatReportTitle;\r\n  FormatDateRange;\r\nend;\r\nraProgram.ComponentNameTitleraProgram.EventNameBeforePrintraProgram.EventID\0\0TraProgramInfor