  if Report.Parameters[\'CompanyPhoneNo\'] <> \'\' then\r\n  begin\r\n    if S <> \'\' then S := S + Sep;\r\n    S := S + \'Phone \' + Report.Parameters[\'CompanyPhoneNo\'];\r\n  end;\r\n  if Report.Parameters[\'CompanyMobileNo\'] <> \'\' then\r\n  begin\r\n    if S <> \'\' then S := S + Sep;\r\n    S := S + \'Mobile \' +  Report.Parameters[\'CompanyMobileNo\'];\r\n  end;\r\n  if Report.Parameters[\'CompanyFaxNo\'] <> \'\' then\r\n  begin\r\n    if S <> \'\' then S := S + Sep;\r\n    S := S + \'Fax \' +  Report.Parameters[\'CompanyFaxNo\'];\r\n  end;\r\n  if Report.Parameters[\'CompanyTin\'] <> \'\' then\r\n  begin\r\n    if S <> \'\' then S := S + Sep;\r\n    S := S + \'Tin \' +  Report.Parameters[\'CompanyTin\'];\r\n  end;\r\n  CompanyContactInfo.Text := S;\r\n  \r\n  if not ByPass then\r\n  begin\r\n    ChrWidth := CompanyContactInfo.Width / Length(CompanyContactInfo.Text);\r\n    CoContactInfoWidth := ChrWidth * (Length(S) - 1);\r\n    CoContactInfoLeft := CompanyContactInfo.Left + \r\n      (CompanyContactInfo.Width - CoContactInfoWidth);\r\n  end;\r\n  if CoContactInfoLeft < HeaderBar.Left then\r\n  begin\r\n    HeaderBar.Left := CoContactInfoLeft;\r\n    HeaderBar.Width := BandWidth - HeaderBar.Left;\r\n  end;\r\n  \r\n  ByPass := True;\r\nend;\r\n\0\0TraProgramInforaProgramInfo2raClassName\nTraProgramraProgram.ChildTyperaProgram.ProgramNameFormatDateRangeraProgram.ProgramTypettProcedureraProgram.Source\Ø\0\0procedure FormatDateRange;\r\nvar\r\n  YearFrom: Integer;\r\n  MonthFrom: Integer;\r\n  DayFrom: Integer;\r\n  YearTo: Integer;\r\n  MonthTo: Integer;\r\n  DayTo: Integer;\r\n  RangeFrom: TDateTime;\r\n  RangeTo: TDateTime;\r\n  S: string;\r\nbegin\r\n  if Report.Parameters.InList(\'RangeTo\') then\r\n  begin\r\n    RangeFrom := Report.Parameters[\'RangeFrom\'];\r\n    RangeTo := Report.Parameters[\'RangeTo\'];\r\n    DecodeDate(RangeFrom, YearFrom, MonthFrom, DayFrom);\r\n    DecodeDate(RangeTo, YearTo, MonthTo, DayTo);\r\n    if YearFrom = YearTo then\r\n    begin\r\n      if MonthFrom = MonthTo then\r\n      begin\r\n        if DayFrom = DayTo then\r\n          S := FormatDateTime(\'mmmm d, yyyy\', RangeTo)\r\n        else\r\n          S := FormatDateTime(\'mmmm \' + IntToStr(DayFrom) +\r\n            \' - \' + IntToStr(DayTo)  + \', yyyy\', RangeTo);\r\n      end\r\n      else\r\n      begin\r\n        S := FormatDateTime(\'mmmm d\', RangeFrom);\r\n        S := S + \' through \' + FormatDateTime(\'mmmm d, yyyy\', RangeTo);\r\n      end;\r\n    end\r\n    else\r\n    begin\r\n      S := FormatDateTime(\'mmmm d, yyyy\', RangeFrom);\r\n      S := S + \' through \' + FormatDateTime(\'mmmm d, yyyy\', RangeTo);\r\n    end;\r\n    DateRangeLabel.Text := S;\r\n  end\r\n  else\r\n    DateRangeLabel.Text := \'All transactions\';\r\nend;\r\n\0\0TraProgramInforaProgramInfo3raClassNameTraEventHandlerraProgram.ProgramNameTitleBeforePrintraProgram.ProgramTypettProcedureraProgram.SourceTprocedure TitleBeforePrint;\r\nbegin\r\n  FormatReportTitle;\r\n  FormatDateRange;\r\nend;\r\nraProgram.ComponentNameTitleraProgram.EventNameBeforePrintraProgram.EventID\0\0TraProgramInforaProgramInfo4raClassNameTraEventHandlerraProgram.ProgramNameTotalAmountOnCalcraProgram.ProgramTypettProcedureraProgram.SourceU\0\0procedure TotalAmountOnCalc(var Value: Variant);\r\nvar\r\n  Accrual: Boolean;\r\nbegin\r\n  Accrual := True;\r\n  if Report.Parameters.InList(\'ReportBasis\') then\r\n    Accrual := Report.Parameters[\'ReportBasis\'] = 0;\r\n  if Accrual then\r\n    Value := plSalesByRepSummary[\'TOTAL_AMOUNT\']\r\n  else\r\n    Value := plSalesByRepSummary[\'AMOUNT_PAID\'];\r\nend;\r\nraProgram.ComponentNameTotalAmountraProgram.EventNameOnCalcraProgram.EventID!\0\0TraProgramInforaProgramInfo5raClassNameTraEventHandlerraProgram.ProgramNameTotalAmountLabelOnCalcraProgram.ProgramTypettProcedureraProgram.Source\0\0procedure TotalAmountLabelOnCalc(var Value: Variant);\r\nbegin\r\