ss then\r\n  begin\r\n    ChrWidth := CompanyContactInfo.Width / Length(CompanyContactInfo.Text);\r\n    CoContactInfoWidth := ChrWidth * (Length(S) - 1);\r\n    CoContactInfoLeft := CompanyContactInfo.Left + \r\n      (CompanyContactInfo.Width - CoContactInfoWidth);\r\n  end;\r\n  if CoContactInfoLeft < HeaderBar.Left then\r\n  begin\r\n    HeaderBar.Left := CoContactInfoLeft;\r\n    HeaderBar.Width := BandWidth - HeaderBar.Left;\r\n  end;\r\n  \r\n  ByPass := True;\r\nend;\r\n\0\0TraProgramInforaProgramInfo4raClassNameTraEventHandlerraProgram.ProgramNameHeaderBeforePrintraProgram.ProgramTypettProcedureraProgram.SourceAprocedure HeaderBeforePrint;\r\nbegin\r\n  FormatReportTitle;\r\nend;\r\nraProgram.ComponentNameHeaderraProgram.EventNameBeforePrintraProgram.EventID\0\0TraProgramInforaProgramInfo5raClassNameTraEventHandlerraProgram.ProgramNameSalesRepNameOnCalcraProgram.ProgramTypettProcedureraProgram.Source²\0\0procedure SalesRepNameOnCalc(var Value: Variant);\r\nbegin\r\n  if plSalesReceipt[\'SALES_REP_FIRST_NAME\'] <> \'\' then\r\n    Value := plSalesReceipt[\'SALES_REP_FIRST_NAME\'];\r\n  if plSalesReceipt[\'SALES_REP_MIDDLE_NAME\'] <> \'\' then\r\n    Value := Value + \' \' + Copy(plSalesReceipt[\'SALES_REP_MIDDLE_NAME\'], 1, 1);\r\n  if plSalesReceipt[\'SALES_REP_LAST_NAME\'] <> \'\' then\r\n    Value := Value + \' \' + plSalesReceipt[\'SALES_REP_LAST_NAME\'];\r\nend;\r\nraProgram.ComponentNameSalesRepNameraProgram.EventNameOnCalcraProgram.EventID!\0\0TraProgramInforaProgramInfo6raClassNameTraEventHandlerraProgram.ProgramNameUnitPriceOnCalcraProgram.ProgramTypettProcedureraProgram.Source®\0\0procedure UnitPriceOnCalc(var Value: Variant);\r\nbegin\r\n  if plSalesReceipt.FieldObjects[\'RATE\'].IsNull then\r\n    Value := \'\'\r\n  else if plSalesReceipt[\'RATE_TYPE\'] = 1 then { percent }\r\n    Value := FormatFloat(\',0.# %\', plSalesReceipt[\'RATE\'])\r\n  else if (plSalesReceipt[\'RATE\'] = 0) and\r\n