eport.Parameters[\'CompanyAddress\']);\r\n  S := \'\';\r\n  Sep := \' â€¢ \';\r\n  if Report.Parameters[\'CompanyEmailAddress\'] <> \'\' then\r\n    S := Report.Parameters[\'CompanyEmailAddress\'];\r\n  if Report.Parameters[\'CompanyPhoneNo\'] <> \'\' then\r\n  begin\r\n    if S <> \'\' then S := S + Sep;\r\n    S := S + \'Phone \' + Report.Parameters[\'CompanyPhoneNo\'];\r\n  end;\r\n  if Report.Parameters[\'CompanyMobileNo\'] <> \'\' then\r\n  begin\r\n    if S <> \'\' then S := S + Sep;\r\n    S := S + \'Mobile \' +  Report.Parameters[\'CompanyMobileNo\'];\r\n  end;\r\n  if Report.Parameters[\'CompanyFaxNo\'] <> \'\' then\r\n  begin\r\n    if S <> \'\' then S := S + Sep;\r\n    S := S + \'Fax \' +  Report.Parameters[\'CompanyFaxNo\'];\r\n  end;\r\n  if Report.Parameters[\'CompanyTin\'] <> \'\' then\r\n  begin\r\n    if S <> \'\' then S := S + Sep;\r\n    S := S + \'Tin \' +  Report.Parameters[\'CompanyTin\'];\r\n  end;\r\n  CompanyContactInfo.Text := S;\r\n  \r\n  if not ByPass then\r\n  begin\r\n    ChrWidth := CompanyContactInfo.Width / Length(CompanyContactInfo.Text);\r\n    CoContactInfoWidth := ChrWidth * (Length(S) - 1);\r\n    CoContactInfoLeft := CompanyContactInfo.Left + \r\n      (CompanyContactInfo.Width - CoContactInfoWidth);\r\n  end;\r\n  if CoContactInfoLeft < HeaderBar.Left then\r\n  begin\r\n    HeaderBar.Left := CoContactInfoLeft;\r\n    HeaderBar.Width := BandWidth - HeaderBar.Left;\r\n  end;\r\n  \r\n  ByPass := True;\r\nend;\r\n\0\0TraProgramInforaProgramInfo2raClassNameTraEventHandlerraProgram.ProgramNameHeaderBeforePrintraProgram.ProgramTypettProcedureraProgram.SourceAprocedure HeaderBeforePrint;\r\nbegin\r\n  FormatReportTitle;\r\nend;\r\nraProgram.ComponentNameHeaderraProgram.EventNameBeforePrintraProgram.EventID\0\0TraProgramInforaProgramInfo3raClassNameTraEventHandlerraProgram.ProgramNameDescriptionOnPrintraProgram.ProgramTypettProcedureraProgram.Source6\0\0procedure DescriptionOnPrint;\r\nvar\r\n  Text: string;\r\nbegin\r\n  if not plBill.FieldObjects[\'DESCRIPTION\'].IsNull then\r\n    Text := plBill[\'DESCRIPTION\']\r\n  else if plBill[\'ITEM_TYPE\'] <= 3 then\r\n    Text := plBill[\'ITEM_PURCHASE_DESC\']\r\n  else\r\n    Text := plBill[\'ITEM_DESC\'];\r\n\r\n  if plBill[\'LINE_TYPE\'] = \'Items\' then\r\n  begin\r\n    if not plBill.FieldObjects[\'QUANTITY\'].IsNull then\r\n    begin\r\n      Text := Text + \', Qty: \' + plBill[\'QUANTITY\'];\r\n      if not plBill.FieldObjects[\'RATE\'].IsNull then\r\n        Text := Text + \' @ \' + FormatFloat(\',0.00\', plBill[\'RATE\']);\r\n    end\r\n    else\r\n    begin\r\n      if (not plBill.FieldObjects[\'RATE\'].IsNull) and\r\n        (plBill[\'RATE_TYPE\'] = 1) then\r\n        Text := Text + \', \' + FormatFloat(\',0.# %\', plBill[\'RATE\']);\r\n    end;\r\n  end;\r\n  Description.Text := Text;\r\nend;\r\nraProgram.ComponentNameDescriptionraProgram.EventNameOnPrintraProgram.EventID \0\0\0TppDesignLayersppDesignLayers1\0TppDesignLayerppDesignLayer1UserName\nForeground	LayerTypeltBandedIndex\0\0\0\0TppParameterListppParameterList2\0TppParameterCompanyName AutoSearchSettings.LogicalPrefix\0AutoSearchSettings.Mandatory	#AutoSearchSettings.SearchExpression\"Argo Distributors, Inc.\"DataTypedtString\ZLookupSettings.DisplayType\ndtNameOnlyLookupSettings.SortOrdersoNameValueArgo Distributors, Inc.UserName\nParameter1\0\0TppParameterCompanyAddress AutoSearchSettings.LogicalPrefix\0AutoSearchSettings.Mandatory	#AutoSearchSettings.SearchExpressionq\"Lot 50 Block 3 Villa Consuelo subd., City Heights, 9500 City of General Santos City, South Cotabato Philippines\"DataTypedtString\ZLookupSettings.DisplayType\ndtNameOnlyLookupSettings.SortOrdersoNameValueoLot 50 Block 3 Villa Consuelo subd., City Heights, 9500 City of General Santos City, South Cotabato Philippines\0\0TppParameterCompanyPhoneNo AutoSearchSettings.LogicalPrefix\0AutoSearchSettings.Mandatory	#AutoSearchSetti