ep: string;\r\n  ChrWidth: Single;\r\n  CoNameWidth: Single;\r\n  CoNameLeft: Single;\r\n  CoContactInfoWidth: Single;\r\n  CoContactInfoLeft: Single;\r\n  BandWidth: Single;\r\n  ByPass: Boolean;\r\nbegin\r\n  BandWidth := (CompanyAddress.Left + CompanyAddress.Width);\r\n  S := Report.Parameters[\'CompanyName\'];\r\n  if not ByPass then\r\n  begin\r\n    ChrWidth := CompanyName.Width / Length(CompanyName.Text);\r\n    CoNameWidth:= ChrWidth * (Length(S) - 1);\r\n    CoNameLeft := CompanyName.Left + (CompanyName.Width - CoNameWidth);\r\n  end;\r\n  HeaderBar.Left := CoNameLeft;\r\n  HeaderBar.Width := BandWidth - HeaderBar.Left;\r\n  CompanyName.Text := S;\r\n  \r\n  CompanyAddress.Lines.Clear;\r\n  CompanyAddress.Lines.Add(Report.Parameters[\'CompanyAddress\']);\r\n  S := \'\';\r\n  Sep := \' â€¢ \';\r\n  if Report.Parameters[\'CompanyEmailAddress\'] <> \'\' then\r\n    S := Report.Parameters[\'CompanyEmailAddress\'];\r\n  if Report.Parameters[\'CompanyPhoneNo\'] <> \'\' then\r\n  begin\r\n    if S <> \'\' then S := S + Sep;\r\n    S := S + \'Phone \' + Report.Parameters[\'CompanyPhoneNo\'];\r\n  end;\r\n  if Report.Parameters[\'CompanyMobileNo\'] <> \'\' then\r\n  begin\r\n    if S <> \'\' then S := S + Sep;\r\n    S := S + \'Mobile \' +  Report.Parameters[\'CompanyMobileNo\'];\r\n  end;\r\n  if Report.Parameters[\'CompanyFaxNo\'] <> \'\' then\r\n  begin\r\n    if S <> \'\' then S := S + Sep;\r\n    S := S + \'Fax \' +  Report.Parameters[\'CompanyFaxNo\'];\r\n  end;\r\n  if Report.Parameters[\'CompanyTin\'] <> \'\' then\r\n  begin\r\n    if S <> \'\' then S := S + Sep;\r\n    S := S + \'Tin \' +  Report.Parameters[\'CompanyTin\'];\r\n  end;\r\n  CompanyContactInfo.Text := S;\r\n  \r\n  if not ByPass then\r\n  begin\r\n    ChrWidth := CompanyContactInfo.Width / Length(CompanyContactInfo.Text);\r\n    CoContactInfoWidth := ChrWidth * (Length(S) - 1);\r\n    CoContactInfoLeft := CompanyContactInfo.Left + \r\n      (CompanyContactInfo.Width - CoContactInfoWidth);\r\n  end;\r\n  if CoContactInfoLeft < HeaderBar.Left then\r\n  begin\r\n    HeaderBar.Left := CoContactInfoLeft;\r\n    HeaderBar.Width := BandWidth - HeaderBar.Left;\r\n  end;\r\n  \r\n  ByPass := True;\r\nend;\r\n\0\0TraProgramInforaProgramInfo2raClassName\nTraProgramraProgram.ChildTyperaProgram.ProgramNameFormatDateRangeraProgram.ProgramTypettProcedureraProgram.Sourceôprocedure FormatDateRange;\r\nbegin\r\n  if Report.Parameters.InList(\'RangeTo\') then\r\n    DateRangeLabel.Text := \'As of \' + FormatDateTime(\'mmmm d, yyyy\', Report.Parameters[\'RangeTo\'])\r\n  else\r\n    DateRangeLabel.Text := \'All transactions\';\r\nend;\r\n\0\0TraProgramInforaProgramInfo3raClassNameTraEventHandlerraProgram.ProgramNameTitleBeforePrintraProgram.ProgramTypettProcedureraProgram.SourceTprocedure TitleBeforePrint;\r\nbegin\r\n  FormatReportTitle;\r\n  FormatDateRange;\r\nend;\r\nraProgram.ComponentNameTitleraProgram.EventNameBeforePrintraProgram.EventID\0\0TraProgramInforaProgramInfo4raClassNameTraEventHandlerraProgram.ProgramNameTotalBalanceOnCalcraProgram.ProgramTypettProcedureraProgram.Sourcenprocedure TotalBalanceOnCalc(var Value: Variant);\r\nbegin\r\n  Value := Value + AccountTypeTotal.Value;\r\n\r\nend;\r\nraProgram.ComponentNameTotalBalanceraProgram.EventNameOnCalcraProgram.EventID!\0\0TraProgramInforaProgramInfo5raClassNameTraEventHandlerraProgram.ProgramNameCategoryHeaderOnCalcraProgram.ProgramTypettProcedureraProgram.Source³procedure CategoryHeaderOnCalc(var Value: Variant);\r\nbegin\r\n  if plBalanceSheet[\'CATEGORY\'] = 0 then\r\n    Value := \'ASSETS\'\r\n  else\r\n    Value := \'LIABILITIES & EQUITY\';\r\n\r\nend;\r\nraProgram.ComponentNameCategoryHeaderraProgram.EventNameOnCalcraProgram.EventID!\0\0TraProgramInforaProgramInfo6raClassNameTraEventHandlerraProgram.ProgramNameAccountTypeGroupLabelOnCalcraProgram.ProgramTypettProcedureraProgram.Sourceˆprocedure AccountTypeGroupLab