eters[\'CompanyFaxNo\'];\r\n  end;\r\n  if Report.Parameters[\'CompanyTin\'] <> \'\' then\r\n  begin\r\n    if S <> \'\' then S := S + Sep;\r\n    S := S + \'Tin \' +  Report.Parameters[\'CompanyTin\'];\r\n  end;\r\n  CompanyContactInfo.Text := S;\r\n  \r\n  if not ByPass then\r\n  begin\r\n    ChrWidth := CompanyContactInfo.Width / Length(CompanyContactInfo.Text);\r\n    CoContactInfoWidth := ChrWidth * (Length(S) - 1);\r\n    CoContactInfoLeft := CompanyContactInfo.Left + \r\n      (CompanyContactInfo.Width - CoContactInfoWidth);\r\n  end;\r\n  if CoContactInfoLeft < HeaderBar.Left then\r\n  begin\r\n    HeaderBar.Left := CoContactInfoLeft;\r\n    HeaderBar.Width := BandWidth - HeaderBar.Left;\r\n  end;\r\n  \r\n  ByPass := True;\r\n\r\nend;\r\n\0\0TraProgramInforaProgramInfo3raClassNameTraEventHandlerraProgram.ProgramName\rChangesOnCalcraProgram.ProgramTypettProcedureraProgram.Source\Þprocedure ChangesOnCalc(var Value: Variant);\r\nbegin\r\n\r\n  Value := (plBankReconciliationList[\'NEW_SYSTEM_BALANCE\']) -\r\n    (plBankReconciliationList[\'SYSTEM_BALANCE\'] + plBankReconciliationList[\'OBJECT_AMOUNT\']); \r\n\r\nend;\r\nraProgram.ComponentNameChangesraProgram.EventNameOnCalcraProgram.EventID!raProgram.CaretPos&\0\0\0TraProgramInforaProgramInfo4raClassNameTraEventHandlerraProgram.ProgramNameTitleBeforePrintraProgram.ProgramTypettProcedureraProgram.SourceTprocedure TitleBeforePrint;\r\nbegin\r\n  FormatReportTitle;\r\n  FormatDateRange;\r\nend;\r\nraProgram.ComponentNameTitleraProgram.EventNameBeforePrintraProgram.EventID\0\0TraProgramInforaProgramInfo5raClassNameTraEventHandlerraProgram.ProgramNameSubTitleOnCalcraProgram.ProgramTypettProcedureraProgram.Source½procedure SubTitleOnCalc(var Value: Variant);\r\nbegin\r\n  if Report.Parameters.InList(\'SubTitle\') then\r\n    Value := Report.Parameters[\'SubTitle\']\r\n  else\r\n    Value := \'All Records\';\r\nend;\r\nraProgram.ComponentNameSubTitleraPr