INSERT INTO `report_item_aging_mapping` VALUES (1,'ITEM_AGING','Item ID','item','ID','INT',1,0,NULL,1),(2,'ITEM_AGING','Item Code','item','CODE','VARCHAR',2,0,NULL,1),(3,'ITEM_AGING','Item Description','item','DESCRIPTION','VARCHAR',3,0,NULL,1),(4,'ITEM_AGING','Batch ID','item_batches','ID','INT',4,0,NULL,1),(5,'ITEM_AGING','Batch No','item_batches','BATCH_NO','VARCHAR',5,0,NULL,1),(6,'ITEM_AGING','Expiry Date','item_batches','EXPIRY_DATE','DATE',6,0,NULL,1),(7,'ITEM_AGING','Location ID','item_inventory','LOCATION_ID','INT',7,0,NULL,1),(8,'ITEM_AGING','Current Quantity','item_inventory','ENDING_QUANTITY','DECIMAL',8,1,'SUM(item_inventory.ENDING_QUANTITY)',1),(9,'ITEM_AGING','Aging Days','item_batches','EXPIRY_DATE','INT',9,1,'DATEDIFF(item_batches.EXPIRY_DATE,CURDATE())',1),(10,'ITEM_AGING','Aging Status','item_batches','EXPIRY_DATE','VARCHAR',10,1,'CASE WHEN EXPIRY_DATE IS NULL THEN \'NO EXPIRY\' WHEN EXPIRY_DATE < CURDATE() THEN \'EXPIRED\' WHEN DATEDIFF(EXPIRY_DATE,CURDATE()) <= 30 THEN \'0-30 DAYS\' WHEN DATEDIFF(EXPIRY_DATE,CURDATE()) <= 60 THEN \'31-60 DAYS\' WHEN DATEDIFF(EXPIRY_DATE,CURDATE()) <= 90 THEN \'61-90 DAYS\' ELSE \'90+ DAYS\' END',1),(19,'ITEM_EXPIRY_AGING','CODE','item','CODE','VARCHAR',1,0,NULL,1),(20,'ITEM_EXPIRY_AGING','DESCRIPTION','item','DESCRIPTION','VARCHAR',2,0,NULL,1),(21,'ITEM_EXPIRY_AGING','BATCH_NUMBER','item_batches','BATCH_NO','VARCHAR',3,0,NULL,1),(22,'ITEM_EXPIRY_AGING','EXPIRY_DATE','item_batches','EXPIRY_DATE','DATE',4,0,NULL,1),(23,'ITEM_EXPIRY_AGING','QTY','item_inventory','ENDING_QUANTITY','DECIMAL',5,0,NULL,1),(24,'ITEM_EXPIRY_AGING','CATEGORY','item_sub_class','DESCRIPTION','VARCHAR',6,1,'CASE\n        WHEN UPPER(TRIM(DESCRIPTION)) = \'MEDICAL\' THEN \'MEDICAL\'\n        WHEN UPPER(TRIM(DESCRIPTION)) = \'DIALYSIS\' THEN \'DIALYSIS\'\n        ELSE \'UNCATEGORIZED\'\n     END',1),(25,'ITEM_EXPIRY_AGING','DAYS','item_batches','EXPIRY_DATE','INTEGER',7,1,'DATEDIFF(EXPIRY_DATE, CURDATE())',1),(26,'ITEM_EXPIRY_AGING','AGING_STATUS','item_batches','EXPIRY_DATE','VARCHAR',8,1,'CASE\n        WHEN EXPIRY_DATE IS NULL THEN \'NO EXPIRY\'\n        WHEN DATEDIFF(EXPIRY_DATE, CURDATE()) < 0 THEN \'EXPIRED\'\n        WHEN DATEDIFF(EXPIRY_DATE, CURDATE()) <= 30 THEN \'0-30 DAYS\'\n        WHEN DATEDIFF(EXPIRY_DATE, CURDATE()) <= 60 THEN \'31-60 DAYS\'\n        WHEN DATEDIFF(EXPIRY_DATE, CURDATE()) <= 90 THEN \'61-90 DAYS\'\n        WHEN DATEDIFF(EXPIRY_DATE, CURDATE()) <= 180 THEN \'91-180 DAYS\'\n        WHEN DATEDIFF(EXPIRY_DATE, CURDATE()) <= 365 THEN \'181-365 DAYS\'\n        ELSE \'>365 DAYS\'\n     END',1);
/*!40000 ALTER TABLE `report_item_aging_mapping` ENABLE KEYS */;
